import{_ as a,o,c as i,a6 as s}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Registro da candidata TikTools 4.2.1-rc.1","description":"","frontmatter":{"title":"Registro da candidata TikTools 4.2.1-rc.1","docId":"releases.4.2.1-rc.1","translationKey":"releases.4.2.1-rc.1","locale":"pt","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"f2b9e975511584a1a6156af8326d7603d73be54f10c97d7e46ed385def4755f6","translationRevision":"0309dc69cc2ea7ebcc5e9a2406d18ce64a39a8728cff4dc80bc63848d2ed1fdc","order":10},"headers":[],"relativePath":"pt/releases/4.2.1-rc.1.md","filePath":"pt/releases/4.2.1-rc.1.md","lastUpdated":1794611623000}'),t={name:"pt/releases/4.2.1-rc.1.md"};function r(d,e,n,c,l,p){return o(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="tiktools-421-rc1" tabindex="-1">TikTools 4.2.1-rc.1 <a class="header-anchor" href="#tiktools-421-rc1" aria-label="Permalink to &quot;TikTools 4.2.1-rc.1 {#tiktools-421-rc1}&quot;">​</a></h1><h2 id="goal-status-and-prerequisites" tabindex="-1">Objetivo, status e pré-requisitos <a class="header-anchor" href="#goal-status-and-prerequisites" aria-label="Permalink to &quot;Objetivo, status e pré-requisitos {#goal-status-and-prerequisites}&quot;">​</a></h2><p>Use este registro histórico de candidata para reproduzir os problemas de recuperação do Cloud, Teams e AppImage Linux investigados na RC1. Ele descreve a base do aplicativo <code>338495a9</code> e uma base separada de backend <code>6a69c99</code>. Estas notas não comprovam a disponibilidade atual de downloads da RC1. Confira os <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">artefatos publicados das versões</a> antes de escolher um instalador.</p><p>A candidata registrada usou pacotes Linux AppImage, DEB e portáteis compilados localmente enquanto Actions estava desativado. Ela não incluiu um instalador Windows recém-compilado. Mantenha um backup e uma cópia isolada do perfil afetado para testar migrações. Colaboração e recuperação de seções do Cloud continuam experimentais.</p><h2 id="changes-in-this-candidate" tabindex="-1">Alterações nesta candidata <a class="header-anchor" href="#changes-in-this-candidate" aria-label="Permalink to &quot;Alterações nesta candidata {#changes-in-this-candidate}&quot;">​</a></h2><ul><li>Settings mantém conta/sessão e diagnósticos; Plugins é responsável por catálogo, pesquisa, Changes e ações de instalação. Modelos e perfis continuam em Automations.</li><li>O painel compartilhado Changes distingue uma comparação com falha de um resultado vazio bem-sucedido. A seção Plugins envia suas próprias seleções/configurações mantendo outras filas e downloads em cache.</li><li>A migração tolera um diretório implícito ausente de plugins incluídos, mantém rigor para caminhos configurados explicitamente e identifica IDs de pacotes ausentes para reparo revisado. Edições e conflitos pendentes são mantidos.</li><li>Teams distingue registrar este PC como host de selecionar um host em outro PC. Convites por apelido vinculam o destinatário selecionado, ainda exigindo aprovação do host.</li><li>A ajuda guiada opcional acompanha o estado da configuração. O empacotamento Linux inclui auxiliares WebKit, plugins GStreamer e o scanner para verificações posteriores de mídia.</li></ul><h2 id="reproduce-and-inspect-the-expected-result" tabindex="-1">Reproduza e inspecione o resultado esperado <a class="header-anchor" href="#reproduce-and-inspect-the-expected-result" aria-label="Permalink to &quot;Reproduza e inspecione o resultado esperado {#reproduce-and-inspect-the-expected-result}&quot;">​</a></h2><ol><li>Registre a versão exibida e o sistema operacional. Abra Plugins → Changes e guarde o erro exato e o ID da requisição se o carregamento falhar.</li><li>No perfil copiado, visualize a migração e revise os IDs exatos de pacotes ausentes antes do reparo. Visualize novamente depois; edições e conflitos pendentes devem continuar presentes.</li><li>Em Teams, registre o PC atual antes de testar seu controle Start. Selecionar o host de outro PC não deve autorizar iniciar este.</li><li>Verifique a inicialização do AppImage e depois áudio/vídeo separadamente. Chegar ao frontend sozinho não comprova reprodução de mídia bem-sucedida.</li></ol><p>Busca por apelido e convites vinculados ao destinatário exigem backend <code>6a69c99</code> e migração <code>20261113000001_remote_invitation_recipients.sql</code>. Instalar esta candidata não implanta esse backend.</p><h2 id="recovery-and-evidence-limits" tabindex="-1">Recuperação e limites das evidências <a class="header-anchor" href="#recovery-and-evidence-limits" aria-label="Permalink to &quot;Recuperação e limites das evidências {#recovery-and-evidence-limits}&quot;">​</a></h2><p>Se uma comparação falhar, mantenha o motivo nativo e tente novamente pelo painel compatível. Não exclua estado pendente nem deduza sucesso de migração por uma verificação de compatibilidade. Colete versão, ação e detalhes de diagnóstico sem dados sensíveis usando o <a href="./../user/preferences/troubleshooting.html">guia de solução de problemas</a>.</p><p>O registro original informa verificações de frontend, mecanismo de sincronização, isolamento de destinatários e dois hosts nativos/relay em sua base. Essas verificações datadas não são uma validação nova de produção. O detentor histórico do bloqueio SQLite não foi identificado. Na RC1, adaptadores Cloud de Variables e Overlays estavam inacabados e Automations comparava uma referência local. Leia as <a href="./4.2.1-rc.3.html">notas da candidata posterior</a> e o <a href="./../user/cloud/changes.html">guia atual de Changes</a> para o escopo seguinte.</p><p>O <a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.1-rc.1.md" target="_blank" rel="noreferrer">registro original da versão</a> é mantido como evidência datada. Volte ao <a href="./">índice de versões</a>.</p>',13)])])}const h=a(t,[["render",r]]);export{m as __pageData,h as default};
